class Solution {
    int[] temp = new int[50000];
    public void merge_sort(int[] nums, int l, int r){
        if(l>=r) return;
        int mid = l+r>>1;
        merge_sort(nums,l,mid);
        merge_sort(nums,mid+1,r);
        int k = 0;
        int i = l;
        int j = mid+1;
        while(i<=mid && j<=r){
            if(nums[i] <= nums[j]){
                temp[k++] = nums[i++];
            } else {
                temp[k++] = nums[j++];
            }
        }
        while(i<=mid) temp[k++] = nums[i++];
        while(j<=r) temp[k++] = nums[j++];
        for(int w=l,m=0; w<=r; w++,m++){
            nums[w] = temp[m];
        }
    }

    public int[] sortArray(int[] nums) {
        int n = nums.length;
        merge_sort(nums,0,n-1);
        return nums;
    }
}
